-- V012 — a task says what done means, and how heavy it looks.
--
-- Two halves beside the description:
--
--   - `criteria` — the **success criteria**: short entered texts under autogenerated ids, one
--     pair per line of what the work is done when. They are what the turn is measured against,
--     so they are sent with the prompt whenever present. A JSON array rather than rows of
--     another table because they are a handful of short lines rewritten whole by the one editor
--     that touches them — the same reason a card's tags are deleted and inserted rather than
--     differenced.
--   - `complexity` — the task's estimation in the Fibonacci suite (1, 2, 3, 5, 8, 13, 21), or
--     NULL for none. Optional, and never sent anywhere: it says how heavy the work looks, not
--     what it is.
--
-- Both live on `task` because both are answers only a task has: a Shutdown and a Scheduler
-- describe no work, so there is nothing of theirs for either to be filed on.

ALTER TABLE task ADD COLUMN criteria jsonb NOT NULL DEFAULT '[]';

ALTER TABLE task ADD COLUMN complexity integer;

-- The suite the selector offers, named where the database can say it: anything else is no
-- complexity at all, and the reads stay forgiving for the same reason every other reader here
-- is — a task is as likely written by hand as by the editor.
ALTER TABLE task ADD CONSTRAINT task_complexity_fibonacci
    CHECK (complexity IS NULL OR complexity IN (1, 2, 3, 5, 8, 13, 21));

COMMENT ON COLUMN task.criteria IS
    'What the work being done means: short entered texts under autogenerated ids, sent with the '
    'prompt whenever present. A task is valid with a title, a description or one of these.';
COMMENT ON COLUMN task.complexity IS
    'The task''s estimation in the Fibonacci suite, or NULL for none. Optional, and never sent '
    'anywhere.';
